js='''const datasets=PAYLOAD;let off=0;const sel=document.getElementById('set'),q=document.getElementById('q');for(const k of Object.keys(datasets)){let o=document.createElement('option');o.textContent=k;sel.append(o)}function draw(){let data=datasets[sel.value],terms=q.value.toLowerCase().trim().split(/\\s+/).filter(Boolean),rs=terms.length?data.rows.filter(r=>terms.every(t=>r.join(' ').toLowerCase().includes(t))):data.rows,cols=data.columns;document.getElementById('count').textContent=`匹配${rs.length}行，显示${off+1}至${Math.min(off+60,rs.length)}`;let t=document.getElementById('table');t.replaceChildren();let tr=document.createElement('tr');for(const c of cols){let th=document.createElement('th');th.textContent=c;tr.append(th)}t.append(tr);for(const r of rs.slice(off,off+60)){tr=document.createElement('tr');for(const v of r){let td=document.createElement('td');td.textContent=v===null?'不可评估':v;tr.append(td)}t.append(tr)}return rs.length}sel.onchange=q.oninput=()=>{off=0;draw()};document.getElementById('next').onclick=()=>{if(off+60<draw())off+=60;draw()};document.getElementById('prev').onclick=()=>{off=Math.max(0,off-60);draw()};draw();'''.replace('PAYLOAD',json.dumps(payload,ensure_ascii=False,allow_nan=False,separators=(',',':')))
